package org.marketreview.nativeapp;
import android.content.Context;
import android.widget.*;
import android.view.View;
import org.json.*;
import java.nio.file.*;
import java.util.*;
public final class ResearchRunsChecks {
 static int checks;static void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
 static JSONObject sample(int id)throws Exception{return new JSONObject().put("id",id).put("runType","knowledge-analysis").put("modelId","historical-model").put("status","completed").put("title","旧研究中文"+id).put("question","这是问题").put("prompt","完整提示词").put("result","完整报告 </tag> 中文\n"+String.join("",Collections.nCopies(240000,"长"))).put("evidence",new JSONArray().put(new JSONObject().put("evidenceId","原始资料").put("quote","逐字引文"))).put("request",new JSONObject().put("code","600001").put("decimal",0.1).put("negative",-0.001).put("wide",1e20)).put("metrics",new JSONObject().put("failure",new JSONObject().put("stage","model_call").put("message","原调用失败"))).put("createdAt","2026-10-11 10:00:00").put("updatedAt","2026-10-11 10:02:00");}
 static void model()throws Exception{JSONObject raw=sample(1),r=ResearchRuns.normalize(raw);JSONObject completeRaw=new JSONObject(raw.toString()).put("unknownExtension",new JSONObject().put("notes",new JSONArray().put("未知原文").put(0.125)).put("link","https://example.org/a/b"));JSONObject whole=new JSONObject().put("version",1).put("exportedAt","2026-10-13").put("tables",new JSONObject().put("researchRuns",new JSONArray().put(completeRaw)).put("expertChannels",new JSONArray().put(new JSONObject().put("id",999).put("unrelated",true))));JSONArray wholeRows=ResearchRuns.decode(whole.toString());check(wholeRows.length()==1&&ResearchRuns.canonical(wholeRows.getJSONObject(0)).equals(ResearchRuns.canonical(ResearchRuns.normalize(completeRaw))),"official tables.researchRuns full record accepted");check(ResearchRuns.canonical(wholeRows.getJSONObject(0).getJSONObject("legacyOriginal")).equals(ResearchRuns.canonical(completeRaw))&&wholeRows.getJSONObject(0).getString("text").equals(raw.getString("result")),"envelope unknown fields and long original retained");check(ResearchRuns.decode(new JSONObject().put("researchRuns",new JSONArray().put(raw)).toString()).length()==1,"standalone old envelope retained");check(ResearchRuns.decode(new JSONObject().put("tables",new JSONObject().put("researchRuns",new JSONArray())).toString()).length()==0,"empty official research array accepted");boolean malformedEnvelope=false;try{ResearchRuns.decode("{\"tables\":{\"researchRuns\":{}}}");}catch(Exception e){malformedEnvelope=true;}check(malformedEnvelope,"nonarray official research table rejected");check(r.getString("text").equals(raw.getString("result")),"long original intact");check(!r.has("instrumentId"),"stock identity not inferred");check(ResearchRuns.read(r).contains("逐字引文")&&ResearchRuns.read(r).contains("原调用失败"),"evidence and failure");check(ResearchRuns.decode(ResearchRuns.backup(new JSONArray().put(r)).toString()).length()==1,"native roundtrip");JSONObject savedMetadata=new JSONObject(r.toString()).put("updatedAt","2026-10-12T00:00:00.000Z");check(ResearchRuns.decode(ResearchRuns.backup(new JSONArray().put(savedMetadata)).toString()).getJSONObject(0).getString("updatedAt").equals("2026-10-12T00:00:00.000Z"),"local timestamp portable and preserved");check(ResearchRuns.preview(new JSONArray().put(r),new JSONArray().put(savedMetadata)).getInt("duplicates")==1,"local timestamp not false conflict");JSONObject invalidTime=new JSONObject(savedMetadata.toString()).put("updatedAt","invalid");boolean timeRejected=false;try{ResearchRuns.decode(ResearchRuns.backup(new JSONArray().put(invalidTime)).toString());}catch(Exception e){timeRejected=true;}check(timeRejected,"invalid local time rejected");boolean rejected=false;try{ResearchRuns.decode(new JSONArray().put(raw).put(raw).toString());}catch(Exception e){rejected=true;}check(rejected,"duplicate ID");JSONObject malformed=new JSONObject(raw.toString()).put("evidence","broken");rejected=false;try{ResearchRuns.normalize(malformed);}catch(Exception e){rejected=true;}check(rejected,"invalid evidence");JSONObject altered=new JSONObject(r.toString()).put("text","其他原文");check(ResearchRuns.preview(new JSONArray().put(altered),new JSONArray().put(r)).getJSONArray("conflicts").length()==1,"conflict preserve");check(ResearchRuns.preview(new JSONArray().put(r),new JSONArray().put(r)).getInt("duplicates")==1,"equal skip");JSONArray many=new JSONArray();for(int i=0;i<123;i++)many.put(ResearchRuns.normalize(sample(i).put("result","行").put("status",i%2==0?"failed":"pending")));check(ResearchRuns.filter(many,"","failed","","").length()==62,"all records filter");check(ResearchRuns.read(many.getJSONObject(1)).contains("旧运行未结束" )==false,"nonempty pending original retained");}
 public static int run(Context context)throws Exception{checks=0;model();BusinessStore store=new BusinessStore(context,"runs-check-"+UUID.randomUUID()+".sqlite");try{ResearchRunsScreen screen=new ResearchRunsScreen(context,store);String input=new JSONArray().put(sample(1)).toString();screen.previewImport(input);check(store.read("reports").length()==0,"preview no write");screen.cancelImport();check(store.read("reports").length()==0,"cancel no write");screen.previewImport(input);screen.confirmImport();check(store.read("reports").length()==1,"explicit merge");check(ResearchRuns.canonical(ResearchRuns.content(store.read("reports").getJSONObject(0))).equals(ResearchRuns.canonical(ResearchRuns.normalize(sample(1)))),"large Android SQLite row retains every original field");JSONObject storedLong=store.read("reports").getJSONObject(0);java.time.Instant.parse(storedLong.getString("updatedAt"));check(ResearchRuns.canonical(ResearchRuns.stored(storedLong)).equals(ResearchRuns.canonical(storedLong)),"local timestamp valid and every stored field retained");String unicode=String.join("",Collections.nCopies(23999,"x"))+"😀"+String.join("",Collections.nCopies(30000,"𐐷中文"))+"终点";store.save("docs",new JSONObject().put("title","分块Unicode原文").put("text",unicode));check(store.read("docs").getJSONObject(0).getString("text").equals(unicode),"chunk boundary preserves supplementary Unicode");ListView list=screen.findViewWithTag("researchRunsList");list.performItemClick(null,0,0);check(((TextView)screen.findViewWithTag("researchRunsOriginal")).getText().toString().contains("完整提示词"),"full reader");JSONObject state=screen.saveState();ResearchRunsScreen reopened=new ResearchRunsScreen(context,store);reopened.restoreState(state);check(((TextView)reopened.findViewWithTag("researchRunsOriginal")).getText().toString().contains("完整提示词"),"reopen exact selection");reopened.previewImport(new JSONArray().put(sample(2)).toString());store.save("reports",new JSONObject().put("title","其他报告").put("text","未覆盖"));reopened.confirmImport();check(store.read("reports").length()==2,"stale preview aborts");JSONObject backup=ResearchRuns.backup(store.read("reports"));check(ResearchRuns.decode(backup.toString()).length()==1,"report-only export isolates other reports");screen.previewImport(new JSONArray().put(sample(3)).toString());JSONObject pendingState=screen.saveState();ResearchRunsScreen pendingPage=new ResearchRunsScreen(context,store);pendingPage.restoreState(pendingState);pendingPage.confirmImport();check(store.read("reports").length()==3,"recreated pending preview explicit merge");JSONArray many=new JSONArray();for(int i=1;i<=123;i++)many.put(ResearchRuns.normalize(sample(i).put("result","行")));JSONArray current=store.read("reports");store.mergeResearchReports(ResearchRuns.preview(many,current).getJSONArray("insert"),current);screen.reload();((Button)screen.findViewWithTag("researchRunsListMode")).performClick();check(list.getCount()==50,"first page 50");((Button)screen.findViewWithTag("researchRunsNext")).performClick();check(list.getCount()==50,"second page 50");((Button)screen.findViewWithTag("researchRunsNext")).performClick();check(list.getCount()==23,"all 123 research rows paginated");JSONObject pagedState=screen.saveState();ResearchRunsScreen paged=new ResearchRunsScreen(context,store);paged.restoreState(pagedState);check(((ListView)paged.findViewWithTag("researchRunsList")).getCount()==23,"pagination survives reconstruction");screen.setDarkTheme(true);screen.setDarkTheme(false);return checks;}finally{store.close();}}
 public static void main(String[] args)throws Exception{checks=0;model();if(args.length>0){String text=new String(Files.readAllBytes(Paths.get(args[0])),java.nio.charset.StandardCharsets.UTF_8);JSONArray decoded=ResearchRuns.decode(text);check(decoded.length()==1,"Qt export imports on Java");if(args.length>1)Files.write(Paths.get(args[1]),ResearchRuns.backup(decoded).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}System.out.println("research runs Java pure: "+checks+" checks GREEN; UI helper device pending root");}
}
